package pcre2

// Constants are generated from the C headers by tools/cdefs. Set PCRE2_SRC to
// the pcre2-10.44 "src" directory and PCRE2_BUILD to the oracle build's "src"
// directory (for config.h), then run "go generate ./...".
//
// Unicode tables are generated by tools/ucdgen (see ucd_gen.go).

//go:generate go run ./tools/cdefs -out consts_gen.go -header "public constants of pcre2.h (PCRE2 10.44)" -skip PCRE2_ZERO_TERMINATED,PCRE2_UNSET,PCRE2_DATE,PCRE2_SIZE,PCRE2_SIZE_MAX -src $PCRE2_SRC/pcre2.h.generic:PCRE2_
//go:generate go run ./tools/cdefs -out internal_gen.go -header "private constants of pcre2_internal.h, pcre2_intmodedep.h, pcre2_compile.c and config.h" -skip PCRE2_DATE -src $PCRE2_BUILD/config.h:HEAP_LIMIT,LINK_SIZE,MATCH_LIMIT,MAX_NAME_COUNT,MAX_NAME_SIZE,MAX_VARLOOKBEHIND,NEWLINE_DEFAULT,PARENS_NEST_LIMIT -src $PCRE2_SRC/pcre2_internal.h -src $PCRE2_SRC/pcre2_intmodedep.h -src $PCRE2_SRC/pcre2_compile.c:META_,ERR,COMPILE_ERROR_BASE,MAX_GROUP_NUMBER,MAX_REPEAT_COUNT,PSKIP_ -src $PCRE2_SRC/pcre2.h.generic:ZZZNONE -table $PCRE2_SRC/pcre2_internal.h:OP_LENGTHS=OP_lengths
//go:generate go run ./tools/cdefs -out ucp_gen.go -header "pcre2_ucp.h: Unicode property codes (general categories, scripts, bidi classes, grapheme break properties, boolean properties)" -src $PCRE2_SRC/pcre2_ucp.h:ucp_
